  useEffect(()=>{if(!started)return;const request=async()=>{try{if(document.visibilityState==='visible'&&'wakeLock'in navigator)wake.current=await(navigator as any).wakeLock.request('screen');}catch{}};void request();document.addEventListener('visibilitychange',request);return()=>{void wake.current?.release();document.removeEventListener('visibilitychange',request);};},[started]);
  const startRest=(duration:number,label:string)=>{if(!duration)return;unlockAudio();setTick(Date.now());setTimer({end:Date.now()+duration*1000,remaining:duration,duration,label,running:true});};
  const toggleTimer=()=>{unlockAudio();setTick(Date.now());setTimer(t=>t.running?{...t,remaining,end:null,running:false}:{...t,end:Date.now()+(t.remaining||t.duration)*1000,remaining:t.remaining||t.duration,running:true,done:false});};
  const addTime=()=>setTimer(t=>({...t,duration:Math.max(t.duration,remaining+30),end:t.running?(t.end||Date.now())+30000:null,remaining:remaining+30,done:false}));
  const setRestDuration=(duration:number)=>{stopAlarm();setTimer({...idleTimer,duration,remaining:duration,label:TIMER_PRESETS.includes(duration)?'Rest timer':'Custom rest'});};
  const openCustomTimer=()=>{setCustomMinutes(String(Math.floor(timer.duration/60)));setCustomSeconds(String(timer.duration%60));setCustomTimerError('');setModal('timer');};
